#!/bin/bash
# Prepares this machine to act as a Bitbucket Pipelines self-hosted Linux Shell runner
# for the development branch pipeline (Kubeflow on localhost:8080).
# The runner credentials (OAuth client id/secret) are generated by Bitbucket itself,
# so the final registration step has to be copied from the Bitbucket UI.

set -e
RUNNER_DIR="$HOME/atlassian-bitbucket-pipelines-runner"

echo "🚀 Preparing Bitbucket Runner (Linux Shell)..."

for cmd in git python3 bash curl tar; do
    command -v "$cmd" >/dev/null || { echo "❌ Missing required command: $cmd"; exit 1; }
done
# The development pipeline uses python3.8 venvs, like the GitLab one.
command -v python3.8 >/dev/null || echo "⚠️  python3.8 not found. Install it, or edit python3.8 -> python3 in bitbucket-pipelines.yml."

mkdir -p "$RUNNER_DIR"

read -p "Path to the downloaded runner .tar.gz (leave empty to skip extraction): " tarball
if [[ -n "$tarball" ]]; then
    tar -xvf "$tarball" -C "$RUNNER_DIR"
fi

echo "✅ Done."
echo "---------------------------------------------------------"
echo "👉 NEXT STEPS:"
echo "1. In Bitbucket: Workspace settings > Pipelines > Workspace runners > Add runner"
echo "   - System and architecture: Linux Shell"
echo "   - Labels: keep the defaults (self.hosted, linux.shell)"
echo "   - Download the runner .tar.gz, extract it to $RUNNER_DIR (or re-run this script)"
echo "2. Copy the start command shown in the wizard and run it inside the extracted folder"
echo "   (do NOT use sudo). The runner shows as ONLINE in Bitbucket when it works."
echo "3. Push to the 'development' branch, the pipeline runs on this machine."
echo "---------------------------------------------------------"
